        add(nome, { tipo: 'divida', cor: dv > 60 ? 'vermelha' : 'laranja', texto: 'Deve ' + brl_(tot) + ' de ' + div.length + (div.length === 1 ? ' sessão' : ' sessões') + ' sem pagamento, a mais antiga de ' + velha.data.slice(0, 5) + ' (' + dv + ' dias)', acao: 'ficha' });
