  try {
    var rr = enviar(); code = rr[0]; txt = rr[1];
    if (comFallback && code === 400 && /fallback/i.test(txt)) { delete body.fallbacks; rr = enviar(); code = rr[0]; txt = rr[1]; } // conta sem acesso ao beta: segue sem
  } catch (e) {
