.fd-resumo{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px}
.fd-resumo div{background:var(--sup);border:1px solid var(--borda);border-radius:14px;padding:12px 14px}
.fd-resumo b{display:block;font-family:var(--fh);font-weight:600;font-size:22px;color:var(--roxo)}
.fd-resumo span{font-size:12px;color:var(--tx2)}
table.cm td,table.cm th{vertical-align:top}
table.cm .td-pac{font-weight:700;min-width:180px}
table.cm .sub{font-size:12px;color:var(--tx3);font-weight:400}
.cpp-linha{display:flex;flex-wrap:wrap;gap:8px 14px;align-items:center;padding:10px 12px;border:1px solid var(--borda);border-radius:12px;background:var(--sup);font-size:14px}
.cpp-linha b{font-weight:700}
.cpp-linha .muted{font-size:12px}
.cob-hoje{white-space:normal;text-align:left;max-width:280px}
.md-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;align-items:start}
.md-grid>div{display:flex;flex-direction:column;gap:16px;min-width:0}
table.cm .acoes{justify-content:flex-end;gap:4px;flex-wrap:wrap}
.td-dec .acoes{justify-content:flex-end;gap:4px;flex-wrap:wrap;max-width:360px;margin-left:auto}
/* Confirmações (Fase 2) */
.cf-lista{display:flex;flex-direction:column;gap:14px}
.cf-grupo.ok{opacity:.75}
.cf-cab{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:6px 14px}
.cf-quem{font-family:var(--fh);font-weight:600;font-size:16px;color:var(--roxo-h)}
.cf-itens{display:flex;flex-direction:column;gap:6px}
.cf-quando{font-weight:700;color:var(--tx2);min-width:120px}
.cf-acoes{display:flex;flex-wrap:wrap;align-items:center;gap:8px}
.cf-fone{display:inline-flex;flex-wrap:wrap;gap:8px;align-items:center}
.cf-fone input{width:220px}
.cf-msg{white-space:pre-wrap;font-family:inherit;font-size:14px;background:var(--bg);border-radius:10px;padding:12px 14px;margin:0}
/* Lançar o dia (Fase 2) */
.ld-lista{display:flex;flex-direction:column;gap:8px}
.ld-item{display:grid;grid-template-columns:minmax(180px,1fr) minmax(0,1.3fr) minmax(240px,1.3fr);gap:8px 14px;align-items:center;padding:10px 12px;border:1px solid var(--borda);border-radius:12px;background:var(--sup)}

.ld-item.marcado{border-color:var(--roxo)}
.ld-item.ok{background:var(--vd-bg);border-color:var(--vd-b)}
.ld-item.erro{border-color:var(--vm-b);background:var(--vm-bg)}
.ld-item .quem{font-weight:700}
.ld-item .sub{font-size:12px;color:var(--tx2)}
.ld-oque{gap:6px!important}
.ld-item .ld-oque button{padding:6px 10px;min-height:34px;font-size:13px}
.ld-extra{display:flex;flex-wrap:wrap;gap:6px 10px;align-items:center;font-size:13px}
.ld-extra input,.ld-extra select{min-height:32px;padding:4px 8px;font-size:13px}
.ld-extra .ld-det{flex:1 1 220px}
@media (max-width:900px){.ld-item{grid-template-columns:1fr}}
/* Ficha do paciente (Fase 2) */
.fi-topo{display:flex;flex-wrap:wrap;align-items:flex-start;gap:10px 16px}
.fi-contatos{display:flex;flex-direction:column;gap:6px;font-size:14px}
.fi-contatos .muted{margin-right:4px}
.fi-off{opacity:.6}
.fi-tab,table.fi-tab{width:100%;border-collapse:collapse;font-size:13px;min-width:0}
.fi-tab th{text-align:left;font-size:12px;color:var(--tx2);padding:6px 8px;border-bottom:1px solid var(--borda)}
.fi-tab td{padding:7px 8px;border-bottom:1px solid var(--borda);vertical-align:top}
.fi-tab tr.apagada td{color:var(--tx2)}
.fi-tab .sub{font-size:12px;color:var(--tx3)}
@media (max-width:900px){.md-grid{grid-template-columns:1fr}}
/* conciliação (Fase 2, 16/10) */
.fd-resumo .atencao b{color:var(--lar-tx)}
.cc-sug{cursor:pointer;align-items:center}
.cc-lados{display:flex;flex-wrap:wrap;align-items:center;gap:6px 12px;flex:1;min-width:0}
.cc-lado{display:flex;flex-wrap:wrap;align-items:center;gap:4px 10px;min-width:0}
.cc-lado .quem{min-width:0;white-space:nowrap}
.cc-recs{flex-direction:column;align-items:flex-start;gap:2px}
.cc-seta{color:var(--tx3);font-weight:700}
.cc-form{display:flex;flex-wrap:wrap;gap:6px;align-items:center;flex:1 1 420px;justify-content:flex-end}
.cc-form select,.cc-form input{width:auto;min-height:36px;padding:6px 10px;font-size:13px;flex:1 1 160px;max-width:260px}
.cc-tab{min-width:620px}
.cc-ia{flex-basis:100%;font-size:13px;margin:2px 0 0}
.cc-ia.faixa{padding:8px 12px}
.cc-ia-corpo{display:flex;flex-wrap:wrap;align-items:center;gap:6px 12px;margin-top:4px}
.cc-ia-corpo .cc-recs{display:flex;flex:1 1 auto}
#cc-res-card summary{cursor:pointer}
@media (max-width:700px){
#cc-resumo{grid-template-columns:repeat(2,minmax(0,1fr))}
.cc-sug{flex-wrap:wrap}
.cc-sug .cc-lados{flex:1 1 calc(100% - 40px)}
.cc-sug>.tag{margin-left:28px;white-space:normal}
.cc-form{flex-basis:100%}
.cc-form select,.cc-form input{max-width:none}
}
/* a receber e perdas (Fase 2, 16/10) */
.ar-faixas button{text-align:left;background:var(--sup);border:1px solid var(--borda);border-radius:14px;padding:12px 14px;cursor:pointer;font:inherit;color:inherit}
.ar-faixas button[aria-pressed="true"]{border-color:var(--roxo);box-shadow:inset 0 0 0 1px var(--roxo)}
.ar-faixas{grid-template-columns:repeat(4,minmax(0,1fr))}
.ar-tab{min-width:680px}
.ar-tab .ar-ck{width:36px}
.ar-tab input[type=checkbox],#ar-todos{width:18px;height:18px;min-height:0;accent-color:var(--roxo)}
.ar-tab tr.sel td{background:#F8F5FA}
.ar-barra{position:sticky;bottom:0;display:flex;flex-wrap:wrap;gap:8px 12px;align-items:center;padding:12px;margin:0 -12px -12px;background:var(--sup);border-top:1px solid var(--borda);border-radius:0 0 14px 14px}
.ar-barra input{flex:1 1 220px;max-width:380px;min-height:38px;padding:7px 12px;font-size:14px}
.ar-barra #ar-sel{font-weight:700}
table.ar-mini{min-width:0}
@media (max-width:700px){ .ar-faixas,#ar-p-resumo{grid-template-columns:repeat(2,minmax(0,1fr))} .ar-barra{bottom:64px} }
/* parcelamentos na Ficha (Fase 2, 16/10) */
.fi-parc{flex-direction:column;align-items:stretch;gap:6px}
.fi-parc-cab{display:flex;flex-wrap:wrap;align-items:center;gap:6px 10px}
.fi-parc .sub{font-size:12px;color:var(--tx3)}
.fi-parc-chips{display:flex;flex-wrap:wrap;gap:4px}
.fi-parc .acoes{display:flex;flex-wrap:wrap;gap:6px}
.fi-parc-form{display:flex;flex-wrap:wrap;gap:8px 10px;align-items:flex-end}
.fi-parc-form .campo{flex:1 1 140px}
.fi-parc-form input,.fi-parc-form select{min-height:38px;padding:7px 10px;font-size:14px}
.fi-parc-novo{display:flex;flex-direction:column;gap:10px;padding:12px;border:1px dashed var(--borda-in);border-radius:12px;margin:8px 0}
.fi-parc-novo .check{margin:4px 0}
@media (max-width:700px){ #fi-resumo{grid-template-columns:repeat(2,minmax(0,1fr))} }
/* alertas (Fase 2, 16/10) */
.alertas{display:flex;flex-direction:column;gap:6px;margin-bottom:8px}
.alerta{display:flex;align-items:center;gap:8px;padding:8px 10px;border-radius:10px;font-size:13px;border-left:4px solid;flex-wrap:wrap}
.alerta svg{flex:none}
.alerta span{flex:1 1 200px;min-width:0}
.alerta.vermelha{background:var(--vm-bg);border-color:var(--vm-tx);color:var(--vm-tx2)}
.alerta.laranja{background:var(--lar-bg);border-color:var(--lar-b);color:var(--pessego-tx)}
.alerta.amarela{background:var(--am-bg);border-color:var(--am-b);color:var(--am-tx)}
.alerta.lilas{background:var(--lilas);border-color:var(--lilas-b);color:var(--roxo-h)}
.alerta.cinza{background:var(--bg);border-color:var(--borda-in);color:var(--tx2)}
.alerta-tag{vertical-align:middle;margin-left:4px;border:0;cursor:pointer;font-family:inherit;min-height:0}
.alerta-tag:hover{filter:brightness(.95);text-decoration:underline}
.fi-alertas:empty{display:none}
</style>
